SELECT metric,value FROM system.asynchronous_metrics WHERE metric IN ('CGroupMaxCPU','CGroupMemoryTotal','CGroupMemoryUsed','CGroupMemoryUsedWithoutPageCache','MemoryResident','UserspacePageCacheBytes','OSMemoryTotal') ORDER BY metric LIMIT 20 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames